      '【转专业·现状】暑假实习空窗被你当成完蛋，却没写成待填项。你把「我不适合」当结论，却还没把「适合」写成可验证条件。重修清单像墙，你在墙根量自己还剩多少力气。\\n\\n【转专业·心事】怕承认不适合，于是把不适合翻译成「再熬熬」。怕被问住，于是躲电话、躲饭局、躲镜子。怕后悔，于是用拖延制造另一种后悔。\\n\\n【转专业·根源】把耳边认同当胜算，胜算不在口舌之间。把「别人的看法」当天气，其实你只能带自己的伞。把世界缩成两条路，其实桌上还有折中与分期。\\n\\n【转专业·落点】落在父母格：用事实抵住音量，不讲输赢；讲清承担与截止；毋须一次说服众人，一次对齐文件即可。',
    spiritLayer:
      '先落名义，不跳空话：转专业在法律与行政意义上是一份合同：甲方是学校规章，乙方是你的时间与钱，附件是培养方案。\\n\\n再落绩点、年限与备案：今日一通官方电话，胜过七日道听途说：记下姓名、分机、答复要点。\\n\\n【转专业·补光】附件未明：先莫争辩；故可以慢，不可隐身。',
