      '【转专业·现状】底层安全感一抖，你就想抓「换专业」当浮木。培养方案读薄了，心还厚着——怕的不是字，是后果。转系论坛刷到眼酸，官方邮箱仍停在草稿箱。\\n\\n【转专业·心事】怕一旦对齐事实就必须行动，于是故意不对齐。怕后悔，于是用拖延制造另一种后悔。怕答案一旦落地就不能改，于是永远停在口头版本。\\n\\n【转专业·根源】把再看一年当缓冲，缓冲里没有还款期。把专业当唯一身份解药，药越吃越窄。把一次拒绝当终审，忘了拒绝后面还有补件与明年。\\n\\n【转专业·落点】读本一声：逼你看清名额、绩点杠、先修与替换学分四件事是否同时满足；这一钥落在纸上，不落在唇舌。',
