      '【转专业·现状】旁人随口一问，你像当庭自辩——比较心在校内竟比校外更尖。热爱两个字好写，课表一摊开就烫手。教室还在老楼，心已在新系招生简章上跑。\\n\\n【转专业·心事】怕被问住，于是躲电话、躲饭局、躲镜子。怕选择后不能回头，于是假装还有无限回头路。怕「再读一年」写在脸上，于是用口罩和帽子遮日程。\\n\\n【转专业·根源】把一次拒绝当终审，忘了拒绝后面还有补件与明年。把「我会想明白」当无限期许可证。把热闹当信息，把孤独当思考——常常反过来。\\n\\n【转专业·落点】落在父母格：用事实抵住音量，不讲输赢；讲清承担与截止；勿以比较心充当信息来源。',
