      '【转专业·牌语】星币七逆位：【转专业·星币逆】若仍假装钱不是问题，先把每月收支与「再读一年」差额写在纸上再回应家里——压力与负荷切忌「到时候再说」。\\n\\n题脉缠在「重修与转」之间——牌在此格替你落锤：父母一句话能改你一整天节奏，你恨这权力又依赖这权力。',
    psychologyLayer:
      '【转专业·现状】热爱两个字好写，课表一摊开就烫手。转成功的样本被你放大，转失败的样本被你清零。你把「问学长」当进度，把「问教务处」当冒险。\\n\\n【转专业·心事】怕钱不够，却不敢把不够写成数字给父母看。怕一旦递交就定型，于是永远「快好了」。怕被说不懂事，于是懂事到不敢要自己的东西。\\n\\n【转专业·根源】把未来当远方灯塔，近处台阶却不敢踩。把热闹当信息，把孤独当思考——常常反过来。把情绪当证据，把沉默当策略。\\n\\n【转专业·落点】不论英雄：只论你有没有核对过文件上的硬条件与软条件；毋须一次说服众人，一次对齐文件即可。',
